// Phase 7 starter drum kit (L266, L267, R1): 20 sampled one-shots for each of the six drum rows,
// spread over the variety map's families and dials (kickoff.md, "Variety map"). Pure data, no audio
// code; Make plays them through kit-drum.ts (slice 1). Every file is CC0 1.0, checked on its own Freesound page on
// 27 Nov 2026; source, author and licence per file are also in public/kits/LICENSES.md.
//
// Files: Freesound's HQ preview of each original, then trimmed (leading silence off, 2 ms fade-in,
// tail cut where it falls 60 dB under the peak or at the row cap: kick, claps, perc 1.5 s; closed
// hat 1 s; open hat 2.5 s; ride 4 s), peak-normalised to -1 dBFS, mono, MP3 128 kbps with a LAME
// gapless header (Chrome and Safari start on the first sample). 1.9 MB for all 120.
// shortcut: picked by name, source and measurement, never auditioned by ear; the owner's listen at the final review is the real check, swap any dud for another CC0 candidate.
// shortcut: built from Freesound's 128 kbps previews (the WAV originals need a Freesound login); swap in the WAVs if hats or rides sound dull.
//
// Measured on the shipped files (decoded): brightnessHz = spectral centroid (2048-point Hann
// frames, hop 512, magnitudes summed from onset to the -20 dB point); lengthS = -20 dB decay (onset
// to the end of the last 10 ms RMS window, 1 ms hop, within 20 dB of the loudest window).
// dirty = hand label for the clean-dirty dial (distorted, bit-crushed or tape-worn sounds).

export type P7Row = "kick" | "clap" | "hat" | "ohat" | "perc" | "ride";
export const P7_ROWS: P7Row[] = ["kick", "clap", "hat", "ohat", "perc", "ride"];

export const P7_ROW_NAMES: Record<P7Row, string> = {
  kick: "Kick", clap: "Claps & snares", hat: "Closed hat", ohat: "Open hat", perc: "Shaker / percussion", ride: "Ride",
};

// The variety map's families per row (kickoff.md, L267), in the map's order.
export const P7_FAMILIES: Record<P7Row, string[]> = {
  kick: ["909 punchy", "808 long boom", "soft round deep-house", "tight short techno", "hard / distorted", "acoustic (live drum)", "lo-fi dusty", "sub-heavy", "clicky top"],
  clap: ["909 clap", "808 clap", "big layered clap", "snap", "rim", "tight snare", "roomy snare", "acoustic snare", "lo-fi snare", "brush"],
  hat: ["909", "808", "acoustic", "tiny tick", "dusty lo-fi", "sizzly bright", "soft shaky"],
  ohat: ["909 open", "808 open", "short open", "long sizzle", "acoustic", "lo-fi"],
  perc: ["shakers", "tambourine", "congas / bongos", "cowbell", "clave / woodblock", "toms", "claps-and-hands"],
  ride: ["909 ride", "acoustic ride", "ride bell", "crash / splash", "sizzle"],
};

export type P7Source = {
  soundId: number; // Freesound sound id
  page: string; // the sound's own Freesound page, where the licence was checked
  title: string; // the uploader's title
  author: string;
  licence: "CC0 1.0";
  sonicPi?: string; // the same recording also ships with Sonic Pi under this name
};

export type P7Sound = {
  id: string;
  name: string; // shown on the shelf (T238): the id without its row, in words ("909 classic", "Lo-fi fat")
  row: P7Row;
  family: string; // one of P7_FAMILIES[row]
  feel: string; // one word
  dirty: boolean;
  brightnessHz: number;
  lengthS: number;
  seconds: number; // file length
  url: string;
  about: string; // one plain line for a beginner
  source: P7Source;
};

